import { lazy } from 'react';
import { GitBranch as IcGitBranch, ListTree as IcListTree, Upload as IcUpload } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * BOM Management — hub page for the Production menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'BOMCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const BOMBuilder = lazy(() => import('./BOMBuilder'));
const BOMModeling = lazy(() => import('./BOMModeling'));
const UploadBOM = lazy(() => import('../../projects/pages/UploadBOM'));

export const TABS = [
  { id: 'builder', label: 'BOM Builder', icon: IcListTree, page: 'BOMBuilder', Component: BOMBuilder },
  { id: 'modeling', label: 'BOM Modeling', icon: IcGitBranch, page: 'BOMModeling', Component: BOMModeling },
  { id: 'upload', label: 'Upload BOM', icon: IcUpload, page: 'UploadBOM', Component: UploadBOM },
];

export default function BOMCenter({ setPage }) {
  return (
    <TabHub
      icon={IcListTree}
      eyebrow="Production"
      title="BOM Management"
      subtitle="Build, model and bulk-upload bills of material"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
